// @generated by ferrox-theme-build: written into the app's output folder
// beside ferrox.css. index.html inlines it in <head>, before the stylesheet:
//   <link data-trunk rel="inline" href="style/ferrox/prepaint.js" />
// It sets data-theme on <html> from the saved choice, so the first paint is
// already in the user's theme; waiting for WASM would flash the default.
(function () {
  try {
    var parts = (localStorage.getItem('ferrox.theme') ||
      localStorage.getItem('webapp-lib.theme') || '').split(':');
    if (parts.length < 4) return;
    var mode = parts[1];
    var dark = mode === 'dark' || (mode === 'system' && window.matchMedia &&
      window.matchMedia('(prefers-color-scheme: dark)').matches);
    var theme = dark ? parts[3] : parts[2];
    if (theme) document.documentElement.setAttribute('data-theme', theme);
  } catch (e) {
    /* A blocked localStorage must not stop the app booting. */
  }
})();
